class Stack:
    def __init__(self):
        self.items = []

    # 推入元素
    def push(self, item):
        self.items.append(item)

    #彈出元素
    def pop(self):
        if not self.is_empty():
            return self.items.pop()
        else:
            return None

    # 檢查堆疊是否為空
    def is_empty(self):
        return len(self.items) == 0

